<template>
  <LabeledValueIcon
    :to="effectiveProjectId ? { name: 'projects-id', params: { id: effectiveProjectId } } : undefined"
    :label="label || 'Project'"
    :value="labelValue"
    :icon="NotebookTextIcon"
    :loading="isLoading"
    :error="error ? 'Failed to load project' : undefined"
  />
</template>
<script setup lang="ts">
import { NotebookTextIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getProjectShortInfo, type ProjectShortInfo2 } from '~/client';

const props = defineProps<{
  label?: string;
  projectId?: string;
  project?: ProjectShortInfo2;
}>();

const effectiveProjectId = computed(() => props.projectId ?? props.project?.id);

const { data, isLoading, error } = useQuery({
  key: () => ['project.short-info', effectiveProjectId.value ?? ''],
  query: () => getProjectShortInfo({ composable: '$fetch', path: { project_id: effectiveProjectId.value ?? '' } }),
  enabled: () => !!effectiveProjectId.value && !props.project,
});

const labelValue = computed(() => props.project?.name ?? data.value?.name);
</script>
